from __future__ import annotations

__doc__ = """
Optional PyCUDA-backed ADAAs and coefficient backend definitions.

The PyCUDA backend is still a stub. This module exists so backend-specific
imports can target a stable path while the implementation evolves.
"""

import ctypes
from pathlib import Path
from typing import Any

import numpy as np

from ....adaa import ComplexArrayADAA, ImagArrayADAA, RealArrayADAA
from ....coeffbackend import CoeffBackend
from ...backend_config import Configuration

PROVIDE_PYCUDA = False

try:
    import pycuda.autoinit  # noqa: F401
    import pycuda.gpuarray as gpuarray
except Exception:
    gpuarray = None
else:
    PROVIDE_PYCUDA = True


class _PyCudaBasicOpsLibrary:
    """Lazy-loaded shared library for PyCUDA coefficient helper operations."""

    _instance = None

    @classmethod
    def get(cls):
        if cls._instance is None:
            cls._instance = cls()
        return cls._instance

    def __init__(self):
        target = self.resolve_target()
        self._lib = ctypes.CDLL(str(target))
        self._last_error = self._lib.phoenix_cuda_support_last_error
        self._last_error.argtypes = []
        self._last_error.restype = ctypes.c_char_p

    @staticmethod
    def resolve_target() -> Path:
        """Return the configured support-library path for the CUDA backend."""
        config = Configuration.for_backend("cuda")
        target = config.get_nested("support", "library_file", default=None)
        if not target:
            raise RuntimeError(
                "missing CUDA backend support library configuration; run "
                "'phoenix-config --dialogue cuda' first"
            )
        path = Path(target)
        if not path.exists():
            raise RuntimeError(
                f"configured CUDA backend support library does not exist: {path}\n"
                "Run 'phoenix-config --dialogue cuda' to regenerate it."
            )
        return path

    @property
    def lib(self):
        return self._lib

    def error_message(self) -> str:
        message = self._last_error()
        if not message:
            return "unknown CUDA support error"
        return message.decode("utf-8", errors="replace")

    @classmethod
    def available(cls) -> bool:
        try:
            cls.resolve_target()
        except RuntimeError:
            return False
        return True


if PROVIDE_PYCUDA:

    def _numpy_dtype(dtype: str):
        match dtype:
            case "f32":
                return np.float32
            case "f64":
                return np.float64
            case "i32":
                return np.int32
            case "i64":
                return np.int64
            case _:
                raise ValueError(f"dtype {dtype} not understood")

    class PyCudaCoeffBackend(CoeffBackend):
        """Experimental PyCUDA coefficient backend."""

        CTYPE_LOOKUP = {
            "f32": ctypes.c_float,
            "f64": ctypes.c_double,
            "i32": ctypes.c_int32,
            "i64": ctypes.c_int64,
        }

        def __init__(self, *args, **kwargs):
            super().__init__(*args, **kwargs)
            self._support_library = None
            self._is_configured = False
            self._support_unavailable = False

        @property
        def support_library(self):
            if self._support_unavailable:
                raise RuntimeError("PyCUDA support library is unavailable")
            if self._support_library is None:
                try:
                    self._support_library = _PyCudaBasicOpsLibrary.get()
                except RuntimeError:
                    self._support_unavailable = True
                    raise
            if not self._is_configured:
                self._is_configured = True
                try:
                    self._configure_ctypes()
                except Exception:
                    self._is_configured = False
                    raise
            return self._support_library

        @property
        def support_ops(self):
            return self.support_library.lib

        def has_native_support(self) -> bool:
            if self._support_unavailable:
                return False
            if self._support_library is not None:
                return True
            if not _PyCudaBasicOpsLibrary.available():
                self._support_unavailable = True
                return False
            return True

        def _configure_ctypes(self):
            if self._support_library is None:
                self._support_library = _PyCudaBasicOpsLibrary.get()
            ops = self._support_library.lib
            for dtype, ctype in type(self).CTYPE_LOOKUP.items():
                zero = getattr(ops, f"coeff_zero_{dtype}")
                zero.argtypes = [ctypes.c_uint64, ctypes.c_size_t]
                zero.restype = ctypes.c_int

                copy = getattr(ops, f"coeff_copy_{dtype}")
                copy.argtypes = [
                    ctypes.c_uint64,
                    ctypes.c_uint64,
                    ctypes.c_size_t,
                ]
                copy.restype = ctypes.c_int

                linop = getattr(ops, f"coeff_linop_{dtype}")
                linop.argtypes = [
                    ctypes.c_uint64,
                    ctype,
                    ctypes.c_uint64,
                    ctypes.c_int,
                    ctype,
                    ctypes.c_uint64,
                    ctypes.c_int,
                    ctypes.c_int,
                    ctypes.c_size_t,
                    ctypes.c_int,
                ]
                linop.restype = ctypes.c_int

        def coeff_new_array(self, size: int, dtype: str):
            return gpuarray.zeros(size, dtype=_numpy_dtype(dtype))

        def _device_pointer(self, coeff_like: Any) -> int:
            if coeff_like is None:
                return 0
            return int(coeff_like.gpudata)

        def _raise_support_error(self, operation: str):
            raise RuntimeError(
                f"PyCUDA coeff backend support call failed in {operation}: "
                f"{self.support_library.error_message()}"
            )

        def coeff_from_numpy(
            self,
            coeff_like: Any,
            nparray: np.ndarray,
            size: int,
            dtype: str,
        ) -> None:
            array = np.asarray(nparray, dtype=_numpy_dtype(dtype))
            array = np.ascontiguousarray(array)
            if size is not None and int(array.size) != int(size):
                raise ValueError(
                    f"Expected input of size {size}, got {array.size}."
                )
            coeff_like.set(array)

        def coeff_to_numpy(
            self, coeff_like: Any, size: int, dtype: str
        ) -> np.ndarray:
            array = np.asarray(coeff_like.get(), dtype=_numpy_dtype(dtype))
            if size is not None and int(array.size) != int(size):
                raise ValueError(
                    f"Expected device array of size {size}, got {array.size}."
                )
            return array

        def coeff_to_zero(self, coeff_like: Any, size: int, dtype: str):
            if coeff_like is None:
                return
            if not self.has_native_support():
                coeff_like.fill(_numpy_dtype(dtype)(0))
                return
            zero = getattr(self.support_ops, f"coeff_zero_{dtype}")
            status = zero(self._device_pointer(coeff_like), size)
            if status != 0:
                self._raise_support_error(f"coeff_zero_{dtype}")

        def coeff_copy_data(self, targ: Any, source: Any, size: int, dtype: str):
            if targ is None:
                return
            if source is None:
                return self.coeff_to_zero(targ, size=size, dtype=dtype)
            if targ is source:
                return
            if not self.has_native_support():
                targ.set(source.get())
                return
            copy = getattr(self.support_ops, f"coeff_copy_{dtype}")
            status = copy(
                self._device_pointer(targ),
                self._device_pointer(source),
                size,
            )
            if status != 0:
                self._raise_support_error(f"coeff_copy_{dtype}")

        def coeff_linop(
            self,
            arr_r: Any,
            /,
            scal_a: float | None,
            arr_x: Any,
            scal_b: float | None,
            arr_y: Any,
            *,
            size: int,
            dtype: str,
            inplace: bool = False,
        ):
            if arr_r is None:
                return
            if size is not None and int(arr_r.size) != int(size):
                raise ValueError(
                    f"Expected output array of size {size}, got {arr_r.size}."
                )
            if not self.has_native_support():
                if not inplace:
                    if arr_x is None:
                        arr_r.fill(_numpy_dtype(dtype)(0))
                    elif scal_a is None:
                        arr_r.set(arr_x.get())
                    else:
                        arr_r.set((scal_a * arr_x).get())
                elif arr_x is not None:
                    if scal_a is None:
                        arr_r.set((arr_r + arr_x).get())
                    else:
                        arr_r.set((arr_r + scal_a * arr_x).get())
                if scal_b is None and arr_y is None:
                    return
                if arr_y is None:
                    return
                if scal_b is None:
                    arr_r.set((arr_r + arr_y).get())
                    return
                arr_r.set((arr_r + scal_b * arr_y).get())
                return
            ctype = type(self).CTYPE_LOOKUP[dtype]
            linop = getattr(self.support_ops, f"coeff_linop_{dtype}")
            x_ptr = self._device_pointer(arr_x)
            y_ptr = self._device_pointer(arr_y)
            has_y = int(arr_y is not None)
            if not has_y:
                scal_b = None
            status = linop(
                self._device_pointer(arr_r),
                ctype(1 if scal_a is None else scal_a),
                x_ptr,
                int(scal_a is not None),
                ctype(0 if scal_b is None else scal_b),
                y_ptr,
                int(scal_b is not None),
                has_y,
                size,
                int(inplace),
            )
            if status != 0:
                self._raise_support_error(f"coeff_linop_{dtype}")


    class PyCudaCA(
        ComplexArrayADAA,
        backend=PyCudaCoeffBackend(),
        identifier="PYCUDA",
        is_anchor=True,
    ):
        """Complex ADAA backed by PyCUDA-managed storage."""


    class PyCudaRA(
        RealArrayADAA,
        backend=PyCudaCoeffBackend(),
        identifier="PYCUDA",
        is_anchor=True,
    ):
        """Real ADAA backed by PyCUDA-managed storage."""


    class PyCudaIA(
        ImagArrayADAA,
        backend=PyCudaCoeffBackend(),
        identifier="PYCUDA",
        is_anchor=True,
    ):
        """Purely imaginary ADAA backed by PyCUDA-managed storage."""


    __all__ = [
        "PROVIDE_PYCUDA",
        "_PyCudaBasicOpsLibrary",
        "PyCudaCoeffBackend",
        "PyCudaCA",
        "PyCudaRA",
        "PyCudaIA",
    ]
else:
    __all__ = ["PROVIDE_PYCUDA", "_PyCudaBasicOpsLibrary"]
